    31→
    32→  /**
    33→   * AST → IR instructions
    34→   * Example: BinaryOp('+', 1, 2) → [PUSH 1, PUSH 2, ADD, HALT]
    35→   *
    36→   * @param ast AST node to compile
    37→   * @param localScope Optional array of parameter names for function scope
    38→   */
    39→  /**
    40→   * Self-Monitoring Kernel: @monitor 어노테이션 함수 body IR 래핑
    41→   *
    42→   * 동작:
    43→   * 1. PUSH fnName → CALL insight_enter  (함수 진입 기록)
    44→   * 2. 원본 body IR (RET 직전에 insight_exit 주입)
    45→   * 3. 마지막 HALT 앞 insight_exit 보장
    46→   *
    47→   * 오버헤드: PUSH + CALL 2개 = ~50ns (TSC 측정 자체보다 낮음)
    48→   */
    49→  wrapWithMonitoring(bodyIR: Inst[], fnName: string): Inst[] {
    50→    const result: Inst[] = [];
    51→
    52→    // 진입 기록: insight_enter(fnName)
    53→    // insight_enter는 null 반환 → VM이 스택에 push하지 않음 → POP 불필요
    54→    result.push({ op: Op.STR_NEW, arg: fnName });
    55→    result.push({ op: Op.CALL, arg: 'insight_enter' });
    56→
    57→    // 원본 IR에서 RET/HALT 직전마다 insight_exit 주입
    58→    for (let i = 0; i < bodyIR.length; i++) {
    59→      const inst = bodyIR[i];
    60→      if (inst.op === Op.RET) {
    61→        // RET 전에 exit 기록. 반환값이 스택 top에 있으므로 건드리지 않음
    62→        result.push({ op: Op.STR_NEW, arg: fnName });
    63→        result.push({ op: Op.CALL, arg: 'insight_exit' });
    64→        result.push(inst);  // RET
    65→      } else if (inst.op === Op.HALT) {
    66→        // HALT 전에 exit 기록 (암묵적 return 없는 함수)
    67→        result.push({ op: Op.STR_NEW, arg: fnName });
    68→        result.push({ op: Op.CALL, arg: 'insight_exit' });
    69→        result.push(inst);  // HALT
    70→      } else {
    71→        result.push(inst);
    72→      }
    73→    }
    74→
    75→    return result;
    76→  }
