    25→  };
    26→  discriminantProperty: string;
    27→}
    28→
    29→/**
    30→ * Type annotation (can be basic, union, conditional, or mapped)
    31→ */
    32→export type TypeAnnotation =
    33→  | string  // 'string', 'number', 'boolean', 'any', etc.
    34→  | UnionType
    35→  | DiscriminatedUnion
    36→  | { type: 'conditional' }  // ConditionalType
    37→  | { type: 'mapped'; key?: string; source?: any; value?: any; optional?: boolean; readonly?: boolean };  // MappedType
    38→
    39→/**
    40→ * Condition for type narrowing
