    42→export interface NarrowingCondition {
    43→  type: 'typeof' | 'instanceof' | 'property-check' | 'truthy' | 'custom';
    44→  variable?: string;
    45→  targetType?: string;
    46→  property?: string;
    47→  value?: any;
    48→  predicate?: string;  // Function name for custom checks
